import React from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../configurations/instance";

function AddOrganisation() {
  const [state, setState] = React.useState({
    title: "",
    email: "",
    role: "Organisation",
    password: "",
  });

  const navigate = useNavigate(); // Хук для навигации

  const handleSubmit = () => {
    const { title, email, role, password } = state;

    axiosInstance
      .post("/organisation/create-org", { title, email, role, password })
      .then((response) => {
        console.log("Организация создана:", response.data);

        // Сохраняем данные в localStorage
        localStorage.setItem("email", email);
        localStorage.setItem("token", response.data.token);

        navigate("/verify-organisation");
      })
      .catch((error) => {
        console.error("Ошибка при создании организации:", error);
      });
  };

  return (
    <div className="organisation-container">
      <h1>Добро Пожаловать!</h1>
      <h3>Чтобы начать регистрацию, заполните форму ниже</h3>
      <form>
        <label htmlFor="organisation">Введите название вашей организации</label>
        <input
          id="organisation"
          value={state.title}
          onChange={(e) => setState({ ...state, title: e.target.value })}
          placeholder="Организация"
        />

        <label htmlFor="email">Введите вашу почту</label>
        <input
          id="email"
          value={state.email}
          onChange={(e) => setState({ ...state, email: e.target.value })}
          placeholder="Почта"
        />

        <label htmlFor="password">Введите пароль</label>
        <input
          id="password"
          type="password"
          value={state.password}
          onChange={(e) => setState({ ...state, password: e.target.value })}
          placeholder="Пароль"
        />

        <button type="button" onClick={handleSubmit}>
          Создать
        </button>
      </form>
    </div>
  );
}

export default AddOrganisation;
